# Surah At-Tawbah (chapter 9) — part 12: ayat 105-114 (IDs 1340-1349)
SURAH = 9

ENTRIES = {
1340: (
"اور کہدو — کام کرو — عنقریب — اللہ — تمہارا عمل — دیکھ لے گا — اور — اس کا رسولؐ اور مؤمن — بھی — اور — تم — غیب و شہادت — کے جاننے والے — کی طرف — لوٹائے جاؤ گے — پس — وہ — تمہیں — تمہارا عمل — بتا دے گا",
"""۱۔ عمل — اللہ، رسولؐ اور مؤمن دیکھتے ہیں۔
۲۔ ’’وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ وَسَتُرَدُّونَ إِلَىٰ عَالِمِ الْغَيْبِ وَالشَّهَادَۃِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ‘‘ — اور کہدو — کام کرو — عنقریب — اللہ — تمہارا عمل — دیکھ لے گا — اور — اس کا رسولؐ اور مؤمن — بھی — اور — تم — غیب و شہادت — کے جاننے والے — کی طرف — لوٹائے جاؤ گے — پس — وہ — تمہیں — تمہارا عمل — بتا دے گا — یعنی اپنے عمل — کو اچھا کرو؛ اللہ اور رسولؐ سب دیکھتے ہیں۔
۳۔ عملی سبق: عمل — چھپ نہیں سکتا — اس لیے — خالص — کرو۔"""
),
1341: (
"اور — کچھ دوسرے لوگ — اللہ کے امر کے — منتظر ہیں — یا تو — وہ — انہیں — عذاب دے گا — یا — ان — کی توبہ قبول کرے گا — اور — اللہ — جاننے والا حکمت والا ہے",
"""۱۔ تبوک سے — پیچھے رہنے والوں میں — کچھ — توبہ کرنے والے تھے۔
۲۔ ’’وَآخَرُونَ مُرْجَوْنَ لِأَمْرِ اللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ وَاللَّهُ عَلِيمٌ حَكِيمٌ‘‘ — اور — کچھ دوسرے لوگ — اللہ کے امر کے — منتظر ہیں — یا تو — وہ — انہیں — عذاب دے گا — یا — ان — کی توبہ قبول کرے گا — اور — اللہ — جاننے والا حکمت والا ہے — یعنی پیچھے رہ جانے والوں میں — کچھ — توبہ کرنے والے — ہیں — ان کا معاملہ — اللہ کے امر کے منتظر ہے۔
۳۔ عملی سبق: توبہ — کبھی — قبول ہوتی ہے — اللہ — فرصت — دیتا ہے۔"""
),
1342: (
"اور — وہ لوگ — جنہوں نے — ضرار مسجد — بنائی — تاکہ — کفر کریں — اور — مؤمنوں میں تفرقہ ڈالیں — اور — ان — لوگوں کے لیے — پناہ گاہ — قائم رکھیں — جو — پہلے — اللہ اور اس کے رسولؐ — سے جنگ کر چکے — اور — وہ — قسمیں کھائیں گے کہ — ہم نے — صرف — بہتری — چاہتی تھی — اور — اللہ — گواہ ہے — کہ — وہ — جھوٹے — ہیں",
"""۱۔ ضرار مسجد — منافقوں کی سازش — مؤمنوں کو تفرقہ ڈالنے کے لیے۔
۲۔ ’’وَالَّذِينَ اتَّخَذُوا مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًا بَيْنَ الْمُؤْمِنِينَ وَإِرْصَادًا لِّمَنْ حَارَبَ اللَّهَ وَرَسُولَهُ مِن قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَا إِلَّا الْحُسْنَىٰ وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَاذِبُونَ‘‘ — اور — وہ لوگ — جنہوں نے — ضرار مسجد — بنائی — تاکہ — کفر کریں — اور — مؤمنوں میں تفرقہ ڈالیں — اور — ان — لوگوں کے لیے — پناہ گاہ — قائم رکھیں — جو — پہلے — اللہ اور اس کے رسولؐ — سے جنگ کر چکے — اور — وہ — قسمیں کھائیں گے کہ — ہم نے — صرف — بہتری — چاہتی تھی — اور — اللہ — گواہ ہے — کہ — وہ — جھوٹے — ہیں — یعنی منافقوں نے مسجدِ ضرار — مؤمنوں میں تفریق اور ابو عامر کا ٹھکانا — بنانے کے لیے — بنائی۔
۳۔ عملی سبق: مسجد — کی نیت — بھی — اللہ کے ہاں — پڑی ہے؛ خالص نیت ضروری ہے۔"""
),
1343: (
"آپؐ — اس میں — کبھی نماز نہ پڑھیں — یقیناً — ایک — مسجد — جو — پہلے دن سے — تقوٰی پر قائم کی گئی — وہ — اس زیادہ لائق ہے — کہ — آپؐ اس میں — نماز پڑھیں — اس میں — ایسے لوگ ہیں — جو — پاک ہونا پسند کرتے ہیں — اور — اللہ — پاک رہنے والوں — کو — پسند کرتا ہے",
"""۱۔ مسجدِ قبا — تقویٰ پر — قائم شدہ — سب سے افضل۔
۲۔ ’’لَا تَقُمْ فِيهِ أَبَدًا لَّمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ‘‘ — آپؐ — اس میں — کبھی نماز نہ پڑھیں — یقیناً — ایک — مسجد — جو — پہلے دن سے — تقوٰی پر قائم کی گئی — وہ — اس زیادہ لائق ہے — کہ — آپؐ اس میں — نماز پڑھیں — اس میں — ایسے لوگ ہیں — جو — پاک ہونا پسند کرتے ہیں — اور — اللہ — پاک رہنے والوں — کو — پسند کرتا ہے — یعنی مسجدِ قبا — تقویٰ پر — قائم شدہ ہے؛ اس میں — پاک رہنے والے لوگ — ہیں اور — اللہ — ایسے لوگوں کو پسند کرتا ہے۔
۳۔ عملی سبق: نیت — مسجد کی بنیاد — ہے؛ تقویٰ — ہمیشہ — سب سے اوپر۔"""
),
1344: (
"کیا — وہ بہتر ہے — جس نے — اپنی — بنیاد — اللہ سے — تقویٰ اور رضامندی پر — رکھی — یا — وہ — جس نے — اپنی — بنیاد — جُرُف کی کنارے — جو — ٹوٹنے والی ہے — رکھی — پس — وہ — اس — کے ساتھ — جہنم میں گرے گی — اور — اللہ — ظالموں کو — ہدایت نہیں دیتا",
"""۱۔ تقویٰ والے کی بنیاد — مستحکم؛ نفاق والے کی — کمزور — جہنم میں گرے گی۔
۲۔ ’’أَفَمَنْ أَسَّسَ بُنْيَانَهُ عَلَىٰ تَقْوَىٰ مِنَ اللَّهِ وَرِضْوَانٍ خَيْرٌ أَمْ مَّنْ أَسَّسَ بُنْيَانَهُ عَلَىٰ شَفَا جُرُفٍ هَارٍ فَانْهَارَ بِهِ فِي نَارِ جَهَنَّمَ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ‘‘ — کیا — وہ بہتر ہے — جس نے — اپنی — بنیاد — اللہ سے — تقویٰ اور رضامندی پر — رکھی — یا — وہ — جس نے — اپنی — بنیاد — جُرُف کی کنارے — جو — ٹوٹنے والی ہے — رکھی — پس — وہ — اس — کے ساتھ — جہنم میں گرے گی — اور — اللہ — ظالموں کو — ہدایت نہیں دیتا — یعنی مسجدِ قبا کی بنیاد — تقویٰ پر ہے؛ منافقوں کی مسجد — ٹوٹنے والے جُرف پر — ہے — وہ — جہنم میں گرے گی۔
۳۔ عملی سبق: بنیاد — مضبوط — ہو — تو — عمارت — قائم رہتی ہے؛ نیت — سب سے — پہلی بنیاد ہے۔"""
),
1345: (
"ان — کی وہ عمارت — جو — انہوں نے بنائی — ان — کے دلوں میں — ہمیشہ — ایک شک — پیدا کرتی رہے گی — جب تک — ان کے دل — ٹکڑے ٹکڑے نہ ہو جائیں — اور — اللہ — جاننے والا حکمت والا ہے",
"""۱۔ مسجدِ ضرار — دلوں میں — شک پیدا کرتی ہے۔
۲۔ ’’لَا يَزَالُ بُنْيَانُهُمُ الَّذِي بَنَوْا رِيبَۃً فِي قُلُوبِهِمْ إِلَّا أَن تَقَطَّعَ قُلُوبُهُمْ وَاللَّهُ عَلِيمٌ حَكِيمٌ‘‘ — ان — کی وہ عمارت — جو — انہوں نے بنائی — ان — کے دلوں میں — ہمیشہ — ایک شک — پیدا کرتی رہے گی — جب تک — ان کے دل — ٹکڑے ٹکڑے نہ ہو جائیں — اور — اللہ — جاننے والا حکمت والا ہے — یعنی ضرار مسجد — ان کے دلوں میں — شک — پیدا کرتی رہے گی — جب تک — ان کے دل — ٹکڑے ٹکڑے نہ ہو جائیں۔
۳۔ عملی سبق: گناہ کی بنیاد — دل میں — شک — پیدا کرتی ہے۔"""
),
1346: (
"بے شک — اللہ — نے — مؤمنوں سے — ان کی جانیں اور مال — جنت کے بدلے — خرید لیے — وہ — اللہ کی راہ میں — لڑتے ہیں — پس — وہ — مارتے ہیں اور — مارے جاتے ہیں — تورات، انجیل اور قرآن — میں — وعدہ — انہی کا ہے — اللہ سے بڑھ کر — وعدہ — وفا کرنے والا کون ہے — پس — تم — اپنی بیع پر — خوش ہو جاؤ — یہ — وہی — عظیم کامیابی — ہے",
"""۱۔ مؤمن — اپنی جانیں — جنت کے بدلے — اللہ کے ہاتھ بیچ دیتے ہیں جہاد میں۔
۲۔ ’’إِنَّ اللَّهَ اشْتَرَىٰ مِنَ الْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَالَهُم بِأَنَّ لَهُمُ الْجَنَّۃَ يُقَاتِلُونَ فِي سَبِيلِ اللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْدًا عَلَيْهِ حَقًّا فِي التَّوْرَاۃِ وَالْإِنجِيلِ وَالْقُرْآنِ وَمَنْ أَوْفَىٰ بِعَهْدِهِ مِنَ اللَّهِ فَاسْتَبْشِرُوا بِبَيْعِكُمُ الَّذِي بَايَعْتُم بِهِ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ‘‘ — بے شک — اللہ — نے — مؤمنوں سے — ان کی جانیں اور مال — جنت کے بدلے — خرید لیے — وہ — اللہ کی راہ میں — لڑتے ہیں — پس — وہ — مارتے ہیں اور — مارے جاتے ہیں — تورات، انجیل اور قرآن — میں — وعدہ — انہی کا ہے — اللہ سے بڑھ کر — وعدہ — وفا کرنے والا کون ہے — پس — تم — اپنی بیع پر — خوش ہو جاؤ — یہ — وہی — عظیم کامیابی — ہے — یعنی اللہ — نے — مؤمنوں سے — جانیں اور مال — جنت کے بدلے — خرید لیے؛ یہ — تورات، انجیل اور قرآن میں — وعدہ ہے؛ یہ — عظیم کامیابی ہے۔
۳۔ عملی سبق: اللہ کی بیع — سب سے — بہترین بیع ہے؛ جہاد — قربانی کا — عظیم موقع ہے۔"""
),
1347: (
"توبہ کرنے والے — عبادت کرنے والے — حمد کرنے والے — روزہ رکھنے والے — رکوع کرنے والے — سجدہ کرنے والے — بھلائی کا حکم دینے والے — برائی سے روکنے والے — اور — اللہ کی حدود — کی — حفاظت کرنے والے — اور — مؤمنوں کو — خوشخبری دے دیجیے",
"""۱۔ مؤمنوں کی — اوصاف — کا جامع بیان۔
۲۔ ’’التَّائِبُونَ الْعَابِدُونَ الْحَامِدُونَ السَّائِحُونَ الرَّاكِعُونَ السَّاجِدُونَ الْآمِرُونَ بِالْمَعْرُوفِ وَالنَّاهُونَ عَنِ الْمُنكَرِ وَالْحَافِظُونَ لِحُدُودِ اللَّهِ وَبَشِّرِ الْمُؤْمِنِينَ‘‘ — توبہ کرنے والے — عبادت کرنے والے — حمد کرنے والے — روزہ رکھنے والے — رکوع کرنے والے — سجدہ کرنے والے — بھلائی کا حکم دینے والے — برائی سے روکنے والے — اور — اللہ کی حدود — کی — حفاظت کرنے والے — اور — مؤمنوں کو — خوشخبری دے دیجیے — یعنی مؤمن — توبہ کرنے والے، عبادت کرنے والے، حمد کرنے والے، روزہ رکھنے والے، رکوع و سجود کرنے والے، بھلائی کا حکم دینے والے، برائی سے روکنے والے اور — اللہ کی حدود — کی حفاظت کرنے والے — ہیں — انہیں — خوشخبری دو۔
۳۔ عملی سبق: مؤمن کی — یہ — دس — صفات — اپنے آپ میں — زندہ کرو۔"""
),
1348: (
"نبیؐ — کے لیے — اور — مؤمنوں کے لیے — مشرکوں کے لیے — استغفار — جائز نہیں — خواہ — وہ — رشتہ دار — ہی ہوں — یہ — بات — ان — کے لیے — واضح ہو جانے کے بعد کہ — وہ — جہنم والے — ہیں",
"""۱۔ مشرک رشتہ دار کے لیے — بھی — استغفار — جائز نہیں۔
۲۔ ’’مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَن يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَىٰ مِن بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ‘‘ — نبیؐ — کے لیے — اور — مؤمنوں کے لیے — مشرکوں کے لیے — استغفار — جائز نہیں — خواہ — وہ — رشتہ دار — ہی ہوں — یہ — بات — ان — کے لیے — واضح ہو جانے کے بعد کہ — وہ — جہنم والے — ہیں — یعنی مشرک کے لیے — استغفار — جائز نہیں — خواہ وہ — رشتہ دار — ہو؛ جب واضح ہو جائے کہ — وہ — جہنم والے ہیں۔
۳۔ عملی سبق: ایمان — رشتے سے بڑھ کر — ہے؛ مشرک کے لیے — دعا — جائز نہیں۔"""
),
1349: (
"ابراہیم کا — اپنے باپ — کے لیے — استغفار — صرف — ایک — وعدہ — تھا — جو — انہوں نے — کیا — تھا — پس — جب — واضح ہو گیا — کہ — وہ — اللہ کا دشمن ہے — تو — وہ — اس سے — براءت اختیار کر گئے — بے شک — ابراہیم — بہت — رحم دل — اور حلیم — تھے",
"""۱۔ ابراہیمؑ — نے پہلے باپ کے لیے استغفار کیا — پھر — براءت اختیار کر لی۔
۲۔ ’’وَمَا كَانَ اسْتِغْفَارُ إِبْرَاهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَۃٍ وَعَدَهَا إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُ أَنَّهُ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ إِنَّ إِبْرَاهِيمَ لَأَوَّاهٌ حَلِيمٌ‘‘ — ابراہیم کا — اپنے باپ — کے لیے — استغفار — صرف — ایک — وعدہ — تھا — جو — انہوں نے — کیا — تھا — پس — جب — واضح ہو گیا — کہ — وہ — اللہ کا دشمن ہے — تو — وہ — اس سے — براءت اختیار کر گئے — بے شک — ابراہیم — بہت — رحم دل — اور حلیم — تھے — یعنی ابراہیم — نے — پہلے باپ کے لیے استغفار کیا — پھر — جب واضح ہوا کہ — وہ — اللہ کا دشمن ہے — تو براءت اختیار کر لی۔
۳۔ عملی سبق: ابراہیمؑ کی طرح — پہلے کوشش کرو؛ اگر — دشمنِ خدا — ہو — تو — براءت — اختیار کرو۔"""
),
}
